/* Tile 1: the request typed into the real Nucleux Input, sent, answered. */
kit.scene('describe', {
  init(kit) {
    kit.stage.append(kit.h('<div class="ground"></div>'));
    this.t1 = window.HWF.tile(kit, 0, 0);
    window.HWF.mark(kit, 'describe');   /* the wordmark, where the intro left it */
  },
  render(t) {
    this.t1.scene.render(Math.max(0, t));
    /* a slow push while it holds, from the tile's top edge */
    this.t1.s.transform = 'scale(' + (1 + 0.0035 * Math.max(0, t)).toFixed(4) + ')';
  },
});
